import urllib.request
import re

url = 'https://books.rakuten.co.jp/search?g=001&sitem=9784044292126'
req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
try:
    with urllib.request.urlopen(req) as res:
        html = res.read().decode('utf-8')
        match = re.search(r'発売日：.*?(\d{4}年\d{2}月)', html)
        if match:
            print('Partial Match:', match.group(1))
        else:
            print('No match')
except Exception as e:
    print('Error:', e)
